def grouper_par(lignes, cle):
    resultat = {}
    for ligne in lignes:
        resultat[ligne[cle]] = resultat.get(ligne[cle], 0) + ligne["montant"]
    return resultat

def mention(moyenne):
    """Renvoie la mention correspondant à une moyenne sur 20."""
    if moyenne >= 16:
        return "très bien"
    elif moyenne >= 14:
        return "bien"
    elif moyenne >= 10:
        return "passable"
    return "insuffisant"

